import * as Game from '../core/game.js';
import {CHAPTERS,CAST,OATH,MENTOR_LESSON,HISTORICAL_NOTES,choiceEchoes,epilogue,sceneLines} from '../data/campaign.js';
import {CONFIG} from '../config.js';
import {drawScene,drawPortrait,drawBattle,pickTile,drawReignCard} from './renderer.js';
import {loadLocal,saveLocal,saveCode,restoreCode} from './storage.js';
import {sound} from './audio.js';
import {heroPortrait,speakerPortrait,chapterScene,loadArt,journeyMap} from './art.js';
import {snapshotEncounter,playEncounterMotion} from './motion.js';

const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let state=null,screen='title',storyIndex=0,selected='hero',action=null,target=null,focusTile=null,formation='shield-wall',orderAction='advance',offline=false,saving=false,lastSaved='',toastTimer,turnBusy=false,saveProblem='',saveConflict=false,pendingImport=null,shareFile=null,feedback='',offlineProgress='',pendingMotion=null,renderTicket=0;
let settings={textScale:1,audio:false,reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches};
try{settings={...settings,...JSON.parse(localStorage.getItem('sacramentum.settings')||'{}')};}catch{}
const roman=n=>['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'][n-1]||n;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const actionNames={move:'Move',strike:'Strike',brace:'Brace',throw:'Throw javelin',assist:'Assist',scout:'Scout',order:'Order',formation:'Formation',rally:'Rally',deploy:'Deploy',persuade:'Persuade',promise:'Promise',threaten:'Threaten',address:'Address chamber',record:'Invoke record',denounce:'Denounce',rebut:'Rebut',oath:'Swear the oath',prepare:'Prepare',negotiate:'Negotiate',stratagem:'Stratagem',allocate:'Allocate',judge:'Judge'};
const actionSymbols={move:'↗',strike:'⚔',brace:'◈',throw:'➶',assist:'✚',scout:'◎',order:'⚑',formation:'▥',rally:'✦',deploy:'⌖',persuade:'◇',promise:'⌁',threaten:'!',address:'◉',record:'▤',denounce:'⚡',rebut:'↶'};
function announce(text){document.querySelector('#announcement').textContent=text;}
function toast(text){
  announce(text);
  if(modal.open){let note=modal.querySelector('.modal-feedback');if(!note){note=document.createElement('p');note.className='notice modal-feedback';note.setAttribute('role','alert');modal.querySelector('.modal-body').prepend(note);}note.textContent=text;note.scrollIntoView({block:'nearest'});return;}
  feedback=text;const inline=document.querySelector('#action-feedback');if(inline){inline.textContent=text;inline.hidden=false;return;}
  let note=document.querySelector('.system-feedback');if(!note){note=document.createElement('p');note.className='system-feedback';note.setAttribute('role','status');document.querySelector('.topbar')?.after(note);}note.textContent=text;note.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>note.hidden=true,6500);
}
function header(){return `<header class="topbar"><button class="brand" data-cmd="home" aria-label="Sacramentum title screen"><img src="./icon.svg" alt=""><span><strong>SACRAMENTUM</strong><small>FROM RECRUIT TO EMPEROR</small></span></button><nav class="topnav" aria-label="Game navigation">${state&&screen!=='title'?'<button class="ghost" data-cmd="map">Campaign</button><button class="ghost wide-nav" data-cmd="journal">Journal</button>':''}<button class="ghost wide-nav" data-cmd="history">Historical notes</button><span class="save-status" role="status">${saving?'Saving…':lastSaved?'✓ Chronicle saved':'A ROMAN CHRONICLE'}</span><button class="ghost" data-cmd="settings" aria-label="Pause and settings">${screen==='title'?'Settings':'Pause'}</button></nav></header>${saveProblem?`<div class="notice" role="alert">${esc(saveProblem)} <button data-cmd="export">Export a save code</button></div>`:''}${offline?'<div class="offline-banner"><span>✓ ALL CHAPTERS AVAILABLE OFFLINE</span><span>Progress saved on this device</span></div>':offlineProgress?`<div class="offline-banner" role="status"><span>${esc(offlineProgress)}</span></div>`:''}`;}
function footer(){return `<footer class="footer"><span>AN ORIGINAL TACTICAL CHRONICLE · c. 250–276 AD</span><span><button class="ghost" data-cmd="help">How to play</button> · <button class="ghost" data-cmd="privacy">Privacy</button> · v${CONFIG.version}</span></footer>`;}
function titleView(){return `${header()}<main id="main" class="title-layout"><section class="title-hero"><div class="title-copy"><p class="eyebrow">THE THIRD CENTURY · AN EMPIRE AT THE EDGE</p><h1>Your journey begins with an oath.<br><em>Your story will become legend.</em></h1><p class="subtitle">From recruit to Emperor.</p><p class="summary">A village boy. A soldier’s oath. An empire that has forgotten how to endure. Earn your command, carry the cost of your choices, and take your place in Rome’s history.</p><div class="title-actions">${state?`<button class="primary" data-cmd="continue">Continue the chronicle <span aria-hidden="true">→</span></button><button data-cmd="new">New game</button>`:`<button class="primary" data-cmd="new">Play · Swear the oath <span aria-hidden="true">→</span></button><button data-cmd="restore">Restore a save</button>`}</div><p class="title-note">TWELVE CHAPTERS · TURN-BASED TACTICS · YOUR LEGACY</p>${state?`<p class="muted" >${esc(state.name)} · Chapter ${roman(state.chapter)} · ${esc(state.rank)}</p>`:''}</div><div class="title-art"><img class="title-illustration" src="./assets/scenes/frontier-oath.webp" width="1536" height="1024" fetchpriority="high" alt="A young recruit with a worn oval shield watches the Danube fortress at dusk"><div class="art-caption"><span>THE DANUBE FRONTIER</span><span>AD CCL</span></div></div></section><section class="title-bottom" aria-label="The path to the purple"><article><span class="roman">I</span><div><h3>Begin with nothing.</h3><p>Hold your shield. Keep your word. Survive the first battle with your comrades.</p></div></article><article><span class="roman">VII</span><div><h3>Earn the standard.</h3><p>Command a legion. Lead a people across a river. Carry their trust into Rome.</p></div></article><article><span class="roman">XII</span><div><h3>Become the oath.</h3><p>Win the Senate and face a rival army. Let the legions swear their loyalty to you.</p></div></article></section></main>${footer()}`;}
function campaignStrip(){return `<nav class="campaign-strip" aria-label="Campaign chapters">${CHAPTERS.map(c=>`<button class="chapter-stop ${c.id===state.chapter?'current':state.completed.includes(c.id)?'complete':'locked'}" data-cmd="chapter-info" data-id="${c.id}" aria-label="Chapter ${c.id}: ${esc(c.title)}, ${state.completed.includes(c.id)?'complete':Game.canAccess(state,c.id)?'available':'locked'}" ${c.id===state.chapter?'aria-current="step"':''}>${state.completed.includes(c.id)?'✓':roman(c.id)}${!Game.canAccess(state,c.id)&&c.id>=11?' ◈':''}</button>`).join('')}</nav>`;}
function chapterHeading(){const ch=Game.getChapter(state);return `<div class="chapter-heading"><div><span class="eyebrow">CHAPTER ${roman(ch.id)} / XII · ${esc(ch.year)}</span><h1>${esc(ch.title)}</h1></div><div class="chapter-meta"><strong>${esc(ch.location)}</strong>${esc(state.rank)} · ${esc(ch.rankMeaning)}</div></div>${campaignStrip()}${state.chapter>=7?`<div class="campaign-meters">${meters()}</div>`:''}`;}
function meters(){const values=state.chapter>=7?['army','political','public']:['army'];const labels={army:'Army loyalty',political:'Political backing',public:'Public confidence'};return `<div class="meters">${values.map(k=>`<div><div class="meter-label"><span>${labels[k]}</span><span>${state.meters[k]} / 100</span></div><div class="meter-track" role="meter" aria-label="${labels[k]}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${state.meters[k]}"><span style="width:${state.meters[k]}%"></span></div></div>`).join('')}</div>`;}
function requirements(){return Game.chapterRequirements(state).map(r=>`<div class="objective-item"><span class="check" aria-hidden="true">${r.done?'✓':'○'}</span><span>${r.done?'Demonstrated':'Learn and use'}: ${esc(actionNames[r.id]||r.id)}</span></div>`).join('');}
function profile(){const ch=Game.getChapter(state);return `<section class="sidebar-card profile-card"><div class="portrait-wrap"><img src="${heroPortrait(state.rank)}" width="360" height="360" decoding="async" alt="${esc(state.name)}, wearing the insignia of ${esc(state.rank)}"></div><div class="eyebrow">YOUR CHARACTER</div><h2 class="portrait-name">${esc(state.name)}</h2><span class="rank-label">${esc(state.rank)} · ${esc(ch.rankMeaning)}</span>${meters()}<div class="rule"></div><div class="resource-row"><span>Supplies</span><strong>${state.supplies}</strong></div><div class="resource-row"><span>Unsettled obligations</span><strong>${state.obligations.filter(o=>o.status==='open').length}</strong></div><button class="ghost small full" data-cmd="character">Character & equipment →</button></section>`;}
function getLines(stage='intro'){return sceneLines?.(Game.getChapter(state),stage,state)||Game.getChapter(state)[stage]||[];}
function story(){const lines=getLines(),line=lines[Math.min(storyIndex,lines.length-1)];if(!line)return '';const who=CAST[line.speaker]?.name||line.speaker;return `<section class="story-card" aria-label="Chapter dialogue"><div class="speaker">${speakerPortrait(line.speaker)?`<img class="avatar-mini" src="${speakerPortrait(line.speaker)}" width="360" height="360" decoding="async" alt="${esc(who)}">`:`<span class="avatar-mini narrator-seal" aria-hidden="true">S</span>`}<div><div class="eyebrow">IN THE CHRONICLE</div><strong>${esc(who)}</strong></div></div><div class="dialogue-text">${esc(line.text)}</div><div class="story-controls"><span class="story-dots" aria-label="Passage ${storyIndex+1} of ${lines.length}">${storyIndex+1} / ${lines.length}</span><div><button class="ghost small" data-cmd="previous-story" ${storyIndex===0?'disabled':''}>← Previous</button><button class="small" data-cmd="next-story" ${storyIndex>=lines.length-1?'disabled':''}>Read on →</button></div></div></section>`;}
function effectsLabel(e={}){const labels={army:'Army',political:'Backing',public:'Public',supplies:'Supplies'};return Object.keys(labels).filter(k=>e[k]).map(k=>`${labels[k]} ${e[k]>0?'+':''}${e[k]}`).join(' · ');}
function decisions(){const d=Game.getChapter(state).decision,picked=state.decisions[d.id];if(picked){const option=d.options.find(o=>o.id===picked);return `<section class="decision-panel"><div class="eyebrow">YOUR DECISION IS RECORDED</div><div class="consequence"><strong>${esc(option.label)}</strong><br>${esc(option.consequence||option.description)}</div></section>`;}return `<section class="decision-panel"><p class="eyebrow">A DECISION THAT WILL FOLLOW YOU</p><h3>${esc(d.prompt)}</h3>${d.options.map(o=>`<button class="choice" data-cmd="choose" data-id="${esc(o.id)}"><strong>${esc(o.label)} <span aria-hidden="true" style="display:inline;float:right">→</span></strong><span>${esc(o.description)}</span><em>${esc(effectsLabel(o.effects))}${o.obligation?' · Creates an obligation':''}</em>${o.obligation?`<span>Owed to ${esc(o.obligation.to)}: ${esc(o.obligation.promise)}. Due at chapter ${esc(o.obligation.due)}. ${esc(o.obligation.consequence)}</span>`:''}</button>`).join('')}</section>`;}
function preparations(){let h='';if(state.chapter===1&&state.encounterIndex>=1){h+=`<section class="oath"><div class="eyebrow">THE SACRAMENTUM · ORIGINAL TEXT</div><blockquote>“${esc(OATH)}”</blockquote><p >Based on the known content of the military oath; this is an original text, not an ancient quotation.</p><button data-cmd="oath" ${state.oath?'disabled':''}>${state.oath?'✓ Oath sworn · lead seal received':'Swear the military oath'}</button></section>`;}
if(state.chapter===7)h+=`<section class="preparation"><div class="eyebrow">A LEGION IS MORE THAN ITS SWORDS</div><h3>Prepare your camp</h3><div class="option-row">${[['fortify','Fortify','Protected starting position'],['rest','Rest','More commander health'],['drill','Drill','Stronger allied strikes'],['march','Forced march','Start farther forward']].map(([id,label,desc])=>`<button data-cmd="prepare" data-id="${id}" class="${state.preparation===id?'chosen':''}" title="${desc}">${label}</button>`).join('')}</div><p class="briefing">Fortify protects your starting position; rest restores the commander; drill improves allied attacks; a forced march advances deployment. In battle, use Deploy before moving.</p></section>`;
if(state.chapter===8&&!state.negotiation)h+=`<section class="preparation"><h3>Negotiate the crossing</h3><p class="briefing">The agreement changes the price of passage. You must still win the council and protect the crossing.</p><div class="option-row"><button data-cmd="negotiate" data-id="safe-passage">Safe passage</button><button data-cmd="negotiate" data-id="grain">Offer grain<br><small>−2 supplies · +3 Public</small></button><button data-cmd="negotiate" data-id="hostages">Demand hostages<br><small>−3 Public · +3 Army</small></button></div></section>`;
if(state.chapter===9)h+=`<section class="preparation"><h3>Choose your stratagem</h3><div class="option-row">${[['night','Night march','Weaken enemy attacks'],['feint','Feigned retreat','Exhaust the heavy cavalry'],['flank','Flank march','Strengthen allied attacks']].map(([id,label,desc])=>`<button data-cmd="stratagem" data-id="${id}" class="${state.stratagem===id?'chosen':''}">${label}<br><small>${desc}</small></button>`).join('')}</div></section>`;
if(state.chapter===10){h+=`<section class="preparation"><h3>Six convoys. Three districts.</h3><p class="briefing">Allocate exactly six grain convoys, with at least one to each district. River relief supports Army Loyalty; the farms build Public Confidence; town relief earns Political Backing.</p>${state.allocation?`<p class="consequence">✓ ${state.allocation.river} to the river · ${state.allocation.farms} to farms · ${state.allocation.town} to town</p>`:`<div class="allocation"><label>River garrisons<input id="river" aria-label="River convoys" type="number" min="1" max="4" value="2"></label><label>Farming villages<input id="farms" aria-label="Farm convoys" type="number" min="1" max="4" value="2"></label><label>Town granaries<input id="town" aria-label="Town convoys" type="number" min="1" max="4" value="2"></label></div><button data-cmd="allocate">Dispatch the convoys</button>`}<div class="rule"></div><h3>Enter the land judgment</h3>${state.judgment?`<p class="consequence">✓ ${state.judgment==='shared'?'Shared tenure':'Settler priority'} recorded. Address the Chamber and Rebut are available.</p>`:`<div class="option-row"><button data-cmd="judge" data-id="shared">Shared tenure<br><small>Protect both communities</small></button><button data-cmd="judge" data-id="settlers">Settler priority<br><small>Existing villagers bear the loss</small></button></div>`}</section>`;}
if(state.chapter===12){const f=Game.finaleForecast(state);h+=`<section class="preparation"><div class="eyebrow">THE ORDER OF BATTLE</div><h3>What your career has brought you</h3><p>${esc(f.description)}</p><p class="briefing">Higher standing strengthens your position. The costly backer remains available. Every route requires a playable confrontation.</p><button data-cmd="ledger">Review obligations →</button>${state.encounterIndex>=1?`<div class="rule"></div><h3>Choose the confrontation</h3>${f.routes.map(r=>`<button class="choice ${state.route===r.id?'chosen':''}" data-cmd="route" data-id="${r.id}"><strong>${esc(r.label)}</strong><span>${esc(r.description)}</span></button>`).join('')}`:''}</section>`;}
return h;}
function camp(){const ch=Game.getChapter(state),next=ch.encounters[state.encounterIndex];return `${header()}<main id="main" class="frame">${chapterHeading()}<div class="camp-grid"><div><div class="camp-mural"><img src="${chapterScene(state.chapter)}" width="720" height="320" decoding="async" alt="Painted impression of ${esc(ch.location)}"><div class="mural-overlay"><p>${esc(ch.description)}</p></div></div>${story()}${decisions()}${preparations()}</div><aside class="camp-side">${profile()}<section class="sidebar-card"><div class="eyebrow">YOUR ORDERS</div><h3 style="margin:8px 0 12px">${esc(next?.title||'Advancement')}</h3><p >${esc(next?.objective||ch.objective)}</p><div class="rule"></div><div class="eyebrow">EARN YOUR NEXT APPOINTMENT</div>${requirements()}<div class="objective-item"><span class="check">${state.encounterIndex===ch.encounters.length?'✓':'○'}</span><span>Complete ${ch.encounters.length} encounters (${state.encounterIndex}/${ch.encounters.length})</span></div><div class="start-block"><button class="primary full" data-cmd="start">${next?.kind==='contest'?'Enter the chamber':'Enter the field'} →</button><p class="muted">Autosave before entering. Retry restores the complete encounter-start checkpoint.</p></div></section><section class="sidebar-card"><div class="eyebrow">THE PROMOTION</div><h3 style="margin:8px 0">${esc(ch.promotion)}</h3><p class="briefing">${esc(ch.promotionMeaning)}</p><p >${esc(ch.reward)}</p><button class="ghost small full" data-cmd="ledger">Obligations & relationships →</button></section></aside></div></main>${footer()}`;}
function selectedUnit(){return state.encounter?.units.find(u=>u.id===selected)||state.encounter?.units.find(u=>u.id==='hero');}
function targets(){return action?Game.getTargets(state,selected,action):[];}
function command(){if(!action||!target)return null;return {unitId:selected,action,x:target.x,y:target.y,...(target.unitId?{targetId:target.unitId}:{}),formation,orderAction};}
function targetLabel(t){const u=state.encounter.units.find(u=>u.id===t.unitId);return `${u?.name||t.label||'Tile'} · ${t.x+1}${String.fromCharCode(65+t.y)}${u?.stance!==undefined?` · stance ${u.stance}`:''}`;}
function actionsPanel(){const e=state.encounter,u=selectedUnit(),actions=Game.getActions(state,selected),ts=targets();if(action&&!actions.includes(action)){action=null;target=null;}const cmd=command(),p=cmd?Game.preview(state,cmd):null;return `<section class="sidebar-card"><div class="eyebrow">${e.kind==='contest'?'YOUR SPEAKER':'SELECTED UNIT'}</div><h3 style="margin:8px 0 4px">${esc(u?.name)}</h3><p class="briefing">Position ${(u?.x??0)+1}${String.fromCharCode(65+(u?.y??0))} · ${esc(e.terrain?.[u?.y]?.[u?.x]||'ground')}<br>${e.kind==='contest'?'Resolve':'Health'} ${u?.resolve??u?.hp} / ${u?.maxResolve??u?.maxHp} · ${u?.moved?'Movement spent':'Movement ready'} · ${u?.acted?'Action spent':'Action ready'}</p>${u?.intent?`<p class="ability-note">Intent: ${esc(u.intent)}</p>`:''}<div class="action-grid" aria-label="Available actions">${actions.map(a=>`<button id="action-${a}" class="${action===a?'active':''}" data-cmd="action" data-id="${a}" aria-pressed="${action===a}"><span class="action-symbol" aria-hidden="true">${actionSymbols[a]||'◇'}</span>${esc(actionNames[a]||a)}</button>`).join('')}</div>${!actions.length?'<p class="briefing">This unit cannot act now. Select another unit or end your turn.</p>':''}${action==='formation'?`<label for="formation-kind" class="eyebrow">FORMATION</label><select id="formation-kind" class="formation-select"><option value="shield-wall" ${formation==='shield-wall'?'selected':''}>Shield wall · protection</option><option value="line" ${formation==='line'?'selected':''}>Line · steady ranks</option><option value="wedge" ${formation==='wedge'?'selected':''}>Wedge · stronger attack</option></select>`:''}${['order','formation'].includes(action)?`<label for="order-kind" class="eyebrow">ORDERED INTENT</label><select id="order-kind" class="formation-select">${[['advance','Advance toward objective'],['attack','Attack nearest enemy'],['hold','Hold position and brace'],['rally','Restore morale']].map(([id,label])=>`<option value="${id}" ${orderAction===id?'selected':''}>${label}</option>`).join('')}</select>`:''}<div class="target-panel"><label for="target-select">${action?'Choose a highlighted target':'Choose an action to preview its effect'}</label><select id="target-select" ${!action||!ts.length?'disabled':''}><option value="">${ts.length?'Select a target…':'No legal targets'}</option>${ts.map((t,i)=>`<option value="${i}" ${target&&t.x===target.x&&t.y===target.y&&t.unitId===target.unitId?'selected':''}>${esc(targetLabel(t))}</option>`).join('')}</select><div class="preview" id="action-preview" role="status">${esc(p?.message||'Nothing is spent until you confirm. Select a target on the map or in the list.')}</div><button id="confirm-action" class="primary full" data-cmd="confirm" ${!p?.ok?'disabled':''}>Confirm ${esc(actionNames[action]||'action')} →</button></div></section>`;}
function battle(){const e=state.encounter,ch=Game.getChapter(state),v=Game.voteCount(state);const units=e.units.filter(u=>['player','ally'].includes(u.side)&&(u.hp??u.resolve)>0);return `${header()}<main id="main" class="frame">${chapterHeading()}<div class="battle-layout"><section class="battle-main"><div class="battle-topline"><div><span class="eyebrow gold">${e.kind==='contest'?'CONTEST · THE POWER OF WORDS':'BATTLE · THE PRICE OF COMMAND'}</span><br><strong>${esc(e.title)}</strong></div><div class="turn-counter">TURN ${e.turn} / ${e.turnLimit}<br>${e.kind==='contest'?`${Math.max(0,e.turnLimit-e.turn+1)} TO THE VOTE`:state.chapter>=4?`${e.commandsLeft} / ${e.commandCapacity} ORDERS`:'ONE SOLDIER. ONE OATH.'}</div></div><div class="battle-stage"><canvas id="battle-board" tabindex="0" role="application" aria-label="Isometric ${e.kind==='contest'?'chamber':'battlefield'}. Arrow keys move the grid cursor. Enter selects a unit or previews a legal target. All targets also available in the target selector."></canvas></div><div class="terrain-legend"><span>★ Your commander</span><span>◆ Allied units</span><span>▼ Rival units</span><span>⚑ Objective</span><span>□ Legal targets</span></div><div class="unit-row" aria-label="Select your unit">${units.map(u=>`<button class="unit-chip ${selected===u.id?'selected':''}" data-cmd="unit" data-id="${esc(u.id)}" aria-pressed="${selected===u.id}"><strong>${u.id==='hero'?'★ ':''}${esc(u.name)}</strong><span>${e.kind==='contest'?'Resolve':'Health'} ${u.resolve??u.hp}/${u.maxResolve??u.maxHp}${u.morale!==undefined?` · morale ${u.morale}`:''}</span></button>`).join('')}</div><p id="action-feedback" class="action-feedback" role="status" ${feedback?'':'hidden'}>${esc(feedback)}</p></section><aside class="battle-actions" aria-label="Selected unit actions">${actionsPanel()}</aside><section class="battle-turns"><div class="turn-tools"><button data-cmd="retry">↶ Retry checkpoint</button><button id="end-turn" class="primary" data-cmd="end-turn" ${e.status!=='active'?'disabled':''}>End turn →</button></div><p class="battle-instructions">Select a unit → choose an action → select a tile or target → confirm. Each unit has one move and one action. ${state.chapter<4?'Allies follow their announced intent; you cannot order them yet.':'Uncommanded allies follow their displayed intent.'}</p>${e.status!=='active'?`<section class="result ${e.status==='won'?'result-won':'result-lost'}" role="status"><div class="eyebrow gold">${e.status==='won'?'OBJECTIVE ACHIEVED':'A SETBACK, NOT THE END'}</div><h2>${e.status==='won'?'The day is yours.':'The field is lost.'}</h2><p>${esc(e.log?.at(-1)||'')}</p>${e.status==='won'?'<button data-cmd="commit">Record the result →</button>':'<button data-cmd="retry">Retry the complete checkpoint</button>'}${e.status==='lost'&&e.kind==='contest'&&!e.fallback?'<p style="margin-top:15px">A patron can fund a new vote: −2 supplies now; owe five supplies and two harvests at accession. You must still win the vote.</p><button data-cmd="fallback">Accept backing and re-run the vote</button>':''}</section>`:''}</section><aside class="battle-side"><section class="sidebar-card"><div class="eyebrow">MISSION OBJECTIVE</div><p style="margin:10px 0">${esc(e.objective)}</p>${requirements()}${v?`<div class="rule"></div><h3>${v.for} / ${v.total} support your motion</h3><p class="briefing">${v.majority} votes needed at the deadline. An early majority does not end the Contest. Withdrawn speakers keep their votes.</p><div class="vote-list">${e.units.filter(u=>u.role==='voter').map(u=>`<span class="vote-dot ${u.stance>=1?'yes':'no'}" title="${esc(u.name)}">${esc(u.bloc)} ${u.stance>=1?'✓':'−'}${Math.abs(u.stance)>=3?' ◈':''}</span>`).join('')}</div>`:''}<button class="ghost small" data-cmd="help">Rules & controls →</button></section><section class="sidebar-card"><div class="eyebrow" style="margin-bottom:12px">FIELD DISPATCHES</div><div class="combat-log" aria-label="Encounter log">${(e.log||[]).slice(-8).reverse().map(text=>`<p>${esc(text)}</p>`).join('')}</div></section></aside></div></main>${footer()}`;}
function promotion(){const ch=Game.getChapter(state);const missing=Game.chapterRequirements(state).filter(r=>!r.done);return `${header()}<main id="main"><section class="promotion"><p class="eyebrow">CHAPTER ${roman(ch.id)} COMPLETE · EARNED THROUGH SERVICE</p><img class="promotion-art" src="${heroPortrait(ch.promotion)}" width="360" height="360" alt="Your portrait wearing the insignia of ${esc(ch.promotion)}"><p class="eyebrow">${ch.id===12?'THE LEGIONS AWAIT THEIR EMPEROR':'YOUR NEXT APPOINTMENT'}</p><h1>${esc(ch.promotion)}</h1><p class="caps">${esc(ch.promotionMeaning)}</p><blockquote>${esc(ch.reward)}</blockquote>${getLines('aftermath').map(l=>`<p>${esc(l.text)}</p>`).join('')}${missing.length?`<p class="notice" style="color:#342b22">Before advancement, demonstrate: ${missing.map(r=>esc(actionNames[r.id]||r.id)).join(', ')}.</p><button data-cmd="replay">Replay the final encounter</button>`:`<button data-cmd="advance">${ch.id===12?'Receive the oath':'Accept the appointment'} →</button>`}</section></main>${footer()}`;}
function ending(){const parts=epilogue(state);return `${header()}<main id="main"><section class="promotion"><p class="eyebrow">THE OATH RETURNS · AD CCLXXVI</p><img class="promotion-art" src="${heroPortrait('Augustus')}" width="360" height="360" alt="${esc(state.name)} in imperial purple"><span class="oath-seal" aria-label="The same lead seal, carried from the first oath">S</span><p class="eyebrow">IMPERATOR CAESAR</p><h1>${esc(state.name)}</h1><p class="caps">Augustus · Emperor of the Romans</p><blockquote>“${esc(OATH)}”</blockquote><p>The same words you spoke as a recruit now rise from a thousand throats. Beneath the purple, the lead seal rests against your heart.</p><p><em>${esc(MENTOR_LESSON)}</em></p><button data-cmd="share">Create your reign card →</button></section><section class="epilogue" aria-label="Your reign and legacy">${parts.map(p=>`<article><div class="eyebrow">THE LEGACY OF YOUR CHOICES</div><h3>${esc(p.title)}</h3><p>${esc(p.text)}</p></article>`).join('')}</section><div class="frame" style="text-align:center"><button data-cmd="journal">Read the full chronicle</button> <button data-cmd="export">Keep a save code</button></div></main>${footer()}`;}
function render(){const ticket=++renderTicket;if(state?.phase==='encounter')document.querySelector('#toast').hidden=true;document.documentElement.dataset.phase=screen==='title'?'title':state?.phase||'camp';document.documentElement.dataset.kind=state?.encounter?.kind||'';document.documentElement.dataset.stage=state?.phase==='epilogue'||(state?.chapter===12&&state?.phase==='promotion')?'imperial':'service';document.documentElement.dataset.reduced=settings.reducedMotion;document.documentElement.style.setProperty('--text-scale',settings.textScale||1);const activeId=document.activeElement?.id;app.innerHTML=screen==='title'?titleView():state?.phase==='encounter'?battle():state?.phase==='promotion'?promotion():state?.phase==='epilogue'?ending():camp();requestAnimationFrame(()=>{if(ticket!==renderTicket)return;paint();bindBoard();if(pendingMotion){playEncounterMotion(document.querySelector('#battle-board'),pendingMotion.before,pendingMotion.after,{reducedMotion:settings.reducedMotion});pendingMotion=null;}if(activeId&&document.getElementById(activeId))document.getElementById(activeId).focus({preventScroll:true});});}
function paint(){if(screen!=='title'&&state?.encounter)drawBattle(document.querySelector('#battle-board'),state.encounter,selected,targets(),focusTile,state.chapter,{action});}
function bindBoard(){const board=document.querySelector('#battle-board');if(!board||!state.encounter)return;board.addEventListener('click',event=>{const p=pickTile(board,state.encounter,event.clientX,event.clientY);selectPoint(p);});board.addEventListener('keydown',event=>{const delta={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]}[event.key];if(delta){event.preventDefault();focusTile??={x:selectedUnit().x,y:selectedUnit().y};focusTile={x:Math.max(0,Math.min(7,focusTile.x+delta[0])),y:Math.max(0,Math.min(7,focusTile.y+delta[1]))};paint();announce(`Grid ${focusTile.x+1}${String.fromCharCode(65+focusTile.y)}. ${state.encounter.units.filter(u=>u.x===focusTile.x&&u.y===focusTile.y&&u.hp>0).map(u=>u.name).join(', ')}`);}if(event.key==='Enter'||event.key===' '){event.preventDefault();selectPoint(focusTile||selectedUnit());}if(event.key==='Escape'){action=null;target=null;render();}});}
function selectPoint(p){const e=state.encounter;if(p.x<0||p.y<0||p.x>=e.width||p.y>=e.height)return;focusTile={x:p.x,y:p.y};const t=targets().find(t=>t.x===p.x&&t.y===p.y);if(action&&t){target=t;render();announce(Game.preview(state,command()).message);return;}const u=e.units.find(u=>['player','ally'].includes(u.side)&&u.x===p.x&&u.y===p.y&&u.hp>0);if(u){selected=u.id;action=null;target=null;render();}else toast(action?'That tile is not a legal target. Choose a highlighted tile or use the target list.':`Tile ${p.x+1}${String.fromCharCode(65+p.y)}. Select a unit first.`);}
async function persist(replace=false){saving=true;const label=document.querySelector('.save-status');if(label)label.textContent='Saving…';try{lastSaved=await saveLocal(state,{replace});saveProblem='';saveConflict=false;}catch(error){lastSaved='';saveProblem=error.message;saveConflict=error.message.includes('another tab');toast(error.message);}finally{saving=false;}}
async function change(fn,{reset=false,tone='click'}={}){if(turnBusy)return;if(saveConflict){toast(saveProblem);return;}turnBusy=true;try{const before=snapshotEncounter(state.encounter);const r=fn();if(r?.ok===false){toast(r.message);return;}if(reset){pendingMotion=null;feedback='';storyIndex=0;selected='hero';action=null;target=null;focusTile=null;}if(!reset)pendingMotion={before,after:snapshotEncounter(state.encounter)};await persist();sound(tone,settings.audio);render();if(r?.message)toast(r.message);}catch(error){toast(`The action could not be completed: ${error.message}`);console.error(error);}finally{turnBusy=false;}}
function showModal(title,body){modal.dataset.panel=title.toLowerCase().replace(/[^a-z]+/g,'-');modal.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="ghost" data-cmd="close-modal" aria-label="Close panel">✕</button></div><div class="modal-body">${body}</div>`;modal.scrollTop=0;if(!modal.open)modal.showModal();else modal.querySelector('[data-cmd="close-modal"]').focus({preventScroll:true});}
function showNew(){showModal('Your chronicle begins',`<p>It is AD 250. You are twenty, newly arrived from a village near the Danube. Your first rank is <strong>Tiro</strong>, a recruit in training. Your name will become part of every oath that follows.</p><label for="name-input">Your Roman name</label><input id="name-input" type="text" maxlength="40" value="Aurelius Marcellus" autocomplete="off">${state?'<p class="notice">Starting a new chronicle replaces the saved campaign on this device. Export a save code first if you want to keep it.</p><button data-cmd="export">Export existing chronicle</button> ':''}<button class="primary" data-cmd="begin">Begin as a recruit →</button><p class="briefing">No account. No downloads required. Progress saves locally. First-play pacing is a design target awaiting human playtesting.</p>`);}
function showMap(id){const chapters=id?[CHAPTERS[id-1]]:CHAPTERS;showModal(id?`Chapter ${roman(id)}`:'The road to the purple',`<p>Twelve chapters, one earned career. The final two chapters are sealed until the required service is complete.</p>${journeyMap(state.chapter,state.completed)}<div class="map-list">${chapters.map(c=>{const open=Game.canAccess(state,c.id);let locked=c.id===11?'Complete chapters I–IX, earn Dux, then complete the governorship in X.':c.id===12?'Complete XI, win its decisive political challenge, and receive Senator status.':`Complete chapter ${roman(c.id-1)} and its promotion requirements.`;return `<article class="map-card ${!open?'locked':''} ${c.id===state.chapter?'current':''}"><div class="eyebrow">${state.completed.includes(c.id)?'✓ COMPLETE':c.id===state.chapter?'● CURRENT CHAPTER':open?'AVAILABLE':'◈ SEALED PREVIEW'} · ${esc(c.year)}</div><h3>${roman(c.id)}. ${esc(c.title)}</h3><p>${esc(c.location)}<br>${esc(c.rank)} → ${esc(c.promotion)}</p><p>${esc(c.objective)}</p>${!open?`<p><strong>Unlock:</strong> ${esc(locked)}</p>`:''}</article>`;}).join('')}</div>`);}
function showLedger(){showModal('Obligations & alliances',`<div class="panel-intro">${meters()}<h3>Promises have a price</h3><p>Promises made during encounters are staged until you commit the result. Retrying restores the checkpoint, including every obligation.</p></div>${state.obligations.length?state.obligations.map(o=>`<article class="obligation"><span class="status-pill">${esc(o.status)}</span><div class="eyebrow">OWED TO</div><h3>${esc(o.to)}</h3><p>${esc(o.promise)}</p><p><strong>Due chapter ${roman(Number(o.due))}</strong> · ${Number(o.cost)||2} supplies to honour</p><p class="briefing">${esc(o.consequence||'Honour the debt at accession or lose public and political trust.')}</p>${state.chapter>=Number(o.due)&&state.phase==='camp'&&o.status==='open'?`<div class="settings-controls"><button data-cmd="settle-honour" data-id="${esc(o.id)}">Honour · ${Number(o.cost)||2} supplies</button><button data-cmd="settle-break" data-id="${esc(o.id)}">Break · −8 Public, −4 Backing</button></div>`:''}</article>`).join(''):'<p class="notice">Your ledger is clear. Future bargains will appear here.</p>'}<h3>The people beside you</h3><div class="alliance-list">${Object.entries(CAST).map(([id,c])=>`<article class="alliance-entry"><img class="avatar-mini" src="${speakerPortrait(id)}" width="360" height="360" loading="lazy" alt="${esc(c.name)}"><div><h3>${esc(c.name)}</h3><p class="rank-label">${esc(c.role)}</p><p>${esc(c.description)}</p>${state.relationships[id]!==undefined?`<span class="status-pill">Relationship ${state.relationships[id]}</span>`:''}</div></article>`).join('')}</div>`);}
function showSettings(){showModal('Pause & settings',`<p>Your game is turn-based. Nothing advances while this panel is open.</p><label class="setting"><span>Generated sound effects<br><small class="muted">The game is fully understandable without sound.</small></span><input id="audio-setting" type="checkbox" ${settings.audio?'checked':''}></label><label class="setting"><span>Reduced motion<br><small class="muted">Disable transition animations.</small></span><input id="motion-setting" type="checkbox" ${settings.reducedMotion?'checked':''}></label><label class="setting"><span>Text size</span><select id="text-size" aria-label="Text size">${[1,1.25,1.5,2].map(n=>`<option value="${n}" ${(settings.textScale||1)===n?'selected':''}>${n*100}%</option>`).join('')}</select></label><div class="settings-controls">${state?'<button data-cmd="export">Copy a save code</button>':''}<button data-cmd="restore">Restore a save code</button><button data-cmd="new">New chronicle</button><button data-cmd="help">Controls & rules</button><button data-cmd="history">Historical notes</button>${state?'<button data-cmd="character">Character</button><button data-cmd="journal">Journal</button><button data-cmd="map">Campaign</button>':''}</div><h3>Keep your chronicle</h3><p>Every action is saved on this device. Retry restores the complete encounter-start checkpoint; your choices before that encounter remain. A new chronicle replaces this local save.</p><p>On iPhone, use Safari’s Share menu → Add to Home Screen. Browsers can clear local data, so keep a save code as a portable backup. ${offline?'All chapter content is cached for offline play.':'Offline content downloads after the production build first opens.'}</p>${!offline&&'serviceWorker'in navigator?'<button data-cmd="retry-offline">Download offline content</button>':''}<button class="primary full" data-cmd="close-modal">Return to the game</button>`);}
function showHelp(){showModal('Controls & rules',`<h3>Every action has a preview</h3><ol><li>Select your commander or an allied unit.</li><li>Choose an action. Legal targets light up on the map.</li><li>Choose a target on the map or from the target list.</li><li>Read the effect and any cost, then press Confirm.</li><li>End turn when ready. Uncommanded allies and enemies act.</li></ol><p><strong>Keyboard:</strong> Tab reaches every control; Enter activates it. On the board, arrow keys move the cursor, Enter selects a unit or target, Escape clears the action. The target selector provides a complete non-spatial route for every action. Native selects use arrow keys.</p><p><strong>Touch:</strong> tap a unit, action, tile or target selector, then Confirm. The map never requires a hover or a double tap.</p><h3>On the battlefield</h3><p>Each unit gets one move and one action. Marsh costs extra movement; water is crossed at fords. Walls and high ground protect units. Flanking reduces defence. Heavy cavalry tires in heat. The commander’s fall loses the battle. Named companions are wounded in tactical defeat; their permanent fate follows signalled narrative choices.</p><p>In chapters I–III you control only yourself. Order unlocks in IV. Formation directs up to three adjacent units for one command, using their existing action limits. Use the intent selector to advance, attack, hold or rally. In VII, Deploy is available only at the opening of battle; it spends movement.</p><h3>In the chamber</h3><p>Each speaker gets one move and one speech. Stance runs from −6 to +6; at +1 a vote supports you. At ±3 commitment hardens and reversing it takes more effort. Persuade changes one adjacent member. Address changes members within three tiles, with a three-turn cooldown. Invoke Record draws strength from your military service.</p><p>Promises shift stance strongly but create a concrete debt: once per recipient, at most two per Contest. Threats cost Public Confidence and harden the bloc. Denounce reduces a rival’s Resolve. Rebut heals a friendly speaker or weakens a rival’s next move.</p><p>Only the deadline vote decides the outcome. A tie fails. A withdrawn speaker cannot act but keeps their vote. Check your required new capabilities before the final turn.</p><h3>Recovery</h3><p>Retry returns to the complete encounter-start state and random seed. A lost political Contest also offers costly backing for a new vote; it never grants a rank by itself. The final chapter always retains a costly backer and minimum force.</p><button class="primary full" data-cmd="close-modal">Understood</button>`);}
function showHistory(){showModal('History & deliberate adaptations',`<p>A historical backbone, a fictional career. Public events remain fixed through Aurelian’s murder in 275; the succession then diverges.</p>${HISTORICAL_NOTES.map(n=>`<article class="history-entry"><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p>${n.url?`<a href="${esc(n.url)}" target="_blank" rel="noopener noreferrer">Read the historical source ↗</a>`:''}</article>`).join('')}<p>Further source notes and uncertainties accompany the source project in docs/historical-research.md.</p>`);}
function showJournal(){const ch=Game.getChapter(state);showModal('The mission journal',`<section class="journal-entry panel-intro"><div class="eyebrow">CURRENT ORDERS · ${esc(ch.year)}</div><h3>${esc(ch.title)}</h3><p>${esc(ch.objective)}</p>${requirements()}</section><section class="journal-entry"><h3>What follows you</h3>${choiceEchoes(state).map(line=>`<p>${esc(typeof line==='string'?line:line.text)}</p>`).join('')}</section><section class="journal-entry"><h3>Campaign record</h3><ol class="chronicle-list">${state.log.slice().reverse().map(t=>`<li>${esc(t)}</li>`).join('')}</ol></section><section class="journal-entry"><h3>Completed encounters</h3>${state.history.length?state.history.map(h=>{const encounter=CHAPTERS.flatMap(c=>c.encounters).find(e=>e.id===h.id);return `<p><span class="status-pill">✓ Complete</span> <strong>${esc(encounter?.title||h.id)}</strong><br>${h.turns} turns · ${h.losses} allied units withdrawn</p>`;}).join(''):'<p>Your first encounter is still ahead.</p>'}</section>`);}
function showCharacter(){const ch=Game.getChapter(state);showModal('Your character & equipment',`<div class="character-layout"><figure class="character-portrait"><img src="${heroPortrait(state.rank)}" width="360" height="360" alt="${esc(state.name)} as ${esc(state.rank)}"><figcaption>${esc(state.rank)} · A life in service</figcaption></figure><div class="character-details"><div class="eyebrow">YOUR CHRONICLE · CHAPTER ${roman(state.chapter)}</div><h3>${esc(state.name)}</h3><p><strong>${esc(state.rank)}</strong> · ${esc(ch.rankMeaning)}<br>Age approximately ${20+Math.round((state.chapter-1)*25/11)} · Danubian birth</p>${meters()}<h3>Equipment & insignia</h3><ul class="equipment-list">${state.inventory.map(i=>`<li><span aria-hidden="true">◇</span><span>${esc(i)}</span></li>`).join('')}</ul><h3>Next appointment: ${esc(ch.promotion)}</h3>${requirements()}<p>${esc(ch.reward)}</p><button data-cmd="ledger">Obligations & alliances →</button></div></div>`);}
async function showExport(){const code=await saveCode(state);showModal('Keep a portable save',`<p>This code contains the entire campaign and current encounter checkpoint. Copy it somewhere safe, then restore it on any device. It contains your chosen name and game decisions; it is never uploaded by the game.</p><label for="save-code">Save code</label><textarea id="save-code" spellcheck="false" readonly>${esc(code)}</textarea><div class="settings-controls"><button class="primary" data-cmd="copy-code">Copy save code</button><button data-cmd="download-code">Download save text</button></div>`);}
function showRestore(){showModal('Restore your chronicle',`<p>Paste a Sacramentum save code. The code is checked before it can replace your current chronicle.</p><label for="restore-file">Or choose a saved text file</label><input id="restore-file" type="file" accept=".txt,.json,text/plain,application/json" style="display:block;margin:12px 0 20px;max-width:100%"><label for="restore-code">Save code</label><textarea id="restore-code" spellcheck="false" placeholder="SAC1.…"></textarea><p class="briefing">A valid import replaces the local campaign. Export the current save first if you need to keep it.</p><button class="primary" data-cmd="import-code">Validate and restore →</button>`);}
async function showShare(){shareFile=null;showModal('Your reign, remembered',`<p>A keepsake of your reign, without character fates or plot twists. The game only shares when you choose the device’s share menu.</p><canvas id="reign-card" class="share-preview" role="img" aria-label="Your reign card"></canvas><div class="settings-controls"><button class="primary" data-cmd="download-card" disabled>Preparing card…</button><button data-cmd="share-card" disabled>Preparing card…</button></div>`);const canvas=document.querySelector('#reign-card');const url=CONFIG.siteUrl||new URL('./',location.href).href;const choices=[state.decisions.ch9==='mercy'?'Mercy after victory':'Order after victory',state.decisions.ch4==='withdraw'?'A commander who preserved the ranks':'A commander who held the line',state.decisions.ch11==='independent'?'A voice earned by service':'Power built on alliances'];const [portrait,scene]=await Promise.all([loadArt(heroPortrait('Augustus')),loadArt(chapterScene(12))]);if(!canvas.isConnected)return;drawReignCard(canvas,{name:state.name,route:state.route,choices,url,portrait,scene});const blob=await new Promise(resolve=>canvas.toBlob(resolve));if(!canvas.isConnected||!blob)return;const downloadButton=modal.querySelector('[data-cmd="download-card"]');downloadButton.disabled=false;downloadButton.textContent='Download card';shareFile=new File([blob],'sacramentum-reign.png',{type:'image/png'});const shareButton=document.querySelector('[data-cmd="share-card"]');if(shareButton){shareButton.disabled=false;shareButton.textContent='Share with your device';}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-cmd]');if(!b||b.disabled)return;const id=b.dataset.id,cmd=b.dataset.cmd;switch(cmd){case 'retry-offline':{const registration=await navigator.serviceWorker.getRegistration();if(registration?.active){registration.active.postMessage('cache-campaign');toast('Downloading the remaining chronicle. Progress appears in the game header.');}else toast('Offline content is available from the production build.');break;}case 'close-modal':modal.close();break;case 'home':screen='title';render();break;case 'new':showNew();break;case 'begin':{const name=document.querySelector('#name-input').value;state=Game.newGame(name);screen='game';storyIndex=0;modal.close();await persist(true);render();toast('Chapter I. You are a Tiro: a recruit in training.');break;}case 'continue':screen='game';storyIndex=0;render();break;case 'map':showMap();break;case 'chapter-info':showMap(Number(id));break;case 'history':showHistory();break;case 'settings':showSettings();break;case 'help':showHelp();break;case 'ledger':showLedger();break;case 'journal':showJournal();break;case 'character':showCharacter();break;case 'privacy':showModal('Your game stays with you','<p>Sacramentum has no account, advertising, analytics, or game server. Saves, settings and offline content stay in this browser. The hosting provider may keep ordinary access logs.</p><p>A save code contains your chosen name and game decisions. A reign card contains your name, broad choices and the game address. Nothing is sent until you copy, download or choose a destination in your device’s share menu.</p><p>Starting a new chronicle replaces the campaign in this browser. Clearing site data removes all local saves. Keep a portable save code if your progress matters to you.</p>');break;case 'next-story':storyIndex=Math.min(storyIndex+1,getLines().length-1);render();break;case 'previous-story':storyIndex=Math.max(0,storyIndex-1);render();break;case 'choose':await change(()=>Game.choose(state,id));break;case 'oath':await change(()=>Game.swearOath(state));break;case 'prepare':await change(()=>Game.prepare(state,id));break;case 'negotiate':await change(()=>Game.negotiate(state,id));break;case 'stratagem':await change(()=>Game.selectStratagem(state,id));break;case 'judge':await change(()=>Game.judge(state,id));break;case 'allocate':await change(()=>Game.allocate(state,{river:Number(document.querySelector('#river').value),farms:Number(document.querySelector('#farms').value),town:Number(document.querySelector('#town').value)}));break;case 'route':await change(()=>{state.route=id;return {ok:true,message:'Confrontation approach selected. Enter the field when ready.'};});break;case 'start':await change(()=>Game.startEncounter(state,state.chapter===12?{route:state.route||'backer'}:{}),{reset:true});break;case 'unit':selected=id;action=null;target=null;render();break;case 'action':{action=id;target=null;const ts=targets();if(ts.length===1)target=ts[0];render();break;}case 'confirm':{const c=command();if(c)await change(()=>Game.act(state,c),{tone:action==='strike'||action==='throw'?'strike':'click'});target=null;action=null;render();break;}case 'end-turn':await change(()=>Game.endTurn(state),{tone:'turn'});action=null;target=null;render();break;case 'retry':showModal('Retry this encounter?',`<p>Restore the complete encounter-start checkpoint: health, positions, random seed, meters, inventory and staged promises. Your earlier campaign decisions stay as they were.</p><button class="primary" data-cmd="retry-confirm">Restore checkpoint</button> <button data-cmd="close-modal">Keep playing</button>`);break;case 'retry-confirm':modal.close();await change(()=>Game.retry(state),{reset:true});break;case 'commit':await change(()=>Game.commitEncounter(state),{reset:true,tone:'promotion'});break;case 'advance':await change(()=>Game.advanceChapter(state),{reset:true,tone:'promotion'});break;case 'fallback':await change(()=>Game.acceptFallback(state),{reset:true});break;case 'replay':if(Game.replayLastEncounter)await change(()=>Game.replayLastEncounter(state),{reset:true});else toast('Use the encounter checkpoint save to return and demonstrate the missing capability.');break;case 'settle-honour':case 'settle-break':await change(()=>Game.settleObligation(state,id,cmd==='settle-honour'));showLedger();break;case 'export':await showExport();break;case 'restore':showRestore();break;case 'copy-code':try{await navigator.clipboard.writeText(document.querySelector('#save-code').value);toast('Save code copied.');}catch{document.querySelector('#save-code').select();toast('Select and copy the highlighted save code.');}break;case 'download-code':download(new Blob([document.querySelector('#save-code').value],{type:'text/plain'}),'sacramentum-save.txt');break;case 'import-code':try{const imported=await restoreCode(document.querySelector('#restore-code').value);pendingImport=imported;showModal('Save code verified',`<p><strong>${esc(imported.name)}</strong><br>Chapter ${roman(imported.chapter)}: ${esc(CHAPTERS[imported.chapter-1].title)}<br>${esc(imported.rank)} · ${imported.history.length} completed encounters</p><p>Restore this verified chronicle and replace the current local campaign?</p><button class="primary" data-cmd="confirm-import">Restore this chronicle</button> <button data-cmd="close-modal">Cancel</button>`);}catch(error){toast(error.message);}break;case 'confirm-import':if(pendingImport){state=pendingImport;pendingImport=null;screen='game';storyIndex=0;selected='hero';action=null;target=null;await persist(true);modal.close();render();toast('Chronicle restored. Chapter access was checked from earned milestones.');}break;case 'share':await showShare();break;case 'download-card':document.querySelector('#reign-card').toBlob(blob=>download(blob,'sacramentum-reign.png'));break;case 'share-card':{const file=shareFile;if(!file){toast('The card is still being prepared.');break;}try{if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:'My Sacramentum reign'});else{download(file,'sacramentum-reign.png');toast('Card downloaded. Share it using your preferred app.');}}catch(error){if(error.name!=='AbortError')toast('Sharing was unavailable. Use Download card.');}break;}}});
document.addEventListener('change',async event=>{if(event.target.id==='restore-file'&&event.target.files?.[0]){const file=event.target.files[0];if(file.size>3000000){toast('Save file is too large.');return;}document.querySelector('#restore-code').value=await file.text();}if(event.target.id==='text-size'){settings.textScale=Number(event.target.value);try{localStorage.setItem('sacramentum.settings',JSON.stringify(settings));}catch{}render();}if(event.target.id==='target-select'){const i=event.target.value;target=i===''?null:targets()[Number(i)];render();if(target)announce(Game.preview(state,command()).message);}if(event.target.id==='formation-kind'){formation=event.target.value;render();}if(event.target.id==='order-kind'){orderAction=event.target.value;render();}if(['audio-setting','motion-setting'].includes(event.target.id)){settings[event.target.id==='audio-setting'?'audio':'reducedMotion']=event.target.checked;try{localStorage.setItem('sacramentum.settings',JSON.stringify(settings));}catch{}document.documentElement.dataset.reduced=settings.reducedMotion;if(settings.audio)sound('click',true);}});
window.addEventListener('resize',()=>requestAnimationFrame(paint));
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state&&!saving)persist();});
window.addEventListener('storage',event=>{if(event.key===CONFIG.saveKey&&state){saveConflict=true;saveProblem='The chronicle changed in another tab. Reload before continuing to avoid overwriting it.';lastSaved='';render();toast(saveProblem);}});
const loaded=await loadLocal();state=loaded.state;render();if(loaded.error)toast(loaded.error);
if('serviceWorker'in navigator){navigator.serviceWorker.addEventListener('message',event=>{if(event.data?.type==='offline-ready'){offline=true;offlineProgress='';render();}else if(event.data?.type==='offline-progress'){offlineProgress=`Preparing offline chronicle · ${event.data.percent}%`;let status=document.querySelector('.offline-banner');if(!status){status=document.createElement('div');status.className='offline-banner';status.setAttribute('role','status');document.querySelector('.topbar')?.after(status);}status.textContent=offlineProgress;}else if(event.data?.type==='offline-error'){offlineProgress=event.data.message;render();}});try{const hadController=Boolean(navigator.serviceWorker.controller);const registration=await navigator.serviceWorker.register('./sw.js');const ready=await navigator.serviceWorker.ready;ready.active?.postMessage('offline-status');const warm=()=>ready.active?.postMessage('cache-campaign');if('requestIdleCallback'in window)requestIdleCallback(warm,{timeout:3000});else setTimeout(warm,1200);registration.addEventListener('updatefound',()=>{registration.installing?.addEventListener('statechange',()=>{if(hadController&&registration.installing?.state==='installed')toast('A new edition is downloaded. Close and reopen the game after saving to use it.');});});}catch{/* Source preview has no generated worker; production build includes it. */}}

